import test from "node:test";
import assert from "node:assert/strict";

import { labelOf, labelProposals, liftNamesRule, RULE_SHOWN_WHOLE_CHARS, ruleLabelProblem } from "./message-labels.ts";
import { ownRuleOf, withoutReplacedWords } from "../store/lift-replacement.ts";

test("labelOf: every form the model may write, and what each means", () => {
  const cases: Array<[string, unknown, unknown]> = [
    ["a rule in the message's own words", "rule", { kind: "rule" }],
    ["not a rule, in any spelling the prompt allows", "Not a rule", { kind: "none" }],
    ["a lift of a rule in the state", "lifts R2", { kind: "lift", targets: ["R2"] }],
    ["a lift of a rule given earlier in this span, by its message", "lifts u7", { kind: "lift", targets: ["u7"] }],
    ["a rule that replaces another", "rule and lifts r1", { kind: "rule", lifts: ["R1"] }],
    ["a rule inside a longer message, with its exact words", { rule: "every option gets a README row" }, { kind: "rule", words: "every option gets a README row" }],
    ["exact words that also replace a rule", { rule: "two-space indentation", lifts: "u2" }, { kind: "rule", words: "two-space indentation", lifts: ["u2"] }],
    ["an object holding only a lift", { lifts: "R3" }, { kind: "lift", targets: ["R3"] }],
    ["a lift of two rules", "lifts R1, R6", { kind: "lift", targets: ["R1", "R6"] }],
    ["a lift of two rules joined by and", "lifts R1 and u4", { kind: "lift", targets: ["R1", "u4"] }],
    ["a rule that replaces two", "rule and lifts R1, R6", { kind: "rule", lifts: ["R1", "R6"] }],
    ["exact words that replace two, as a list", { rule: "two-space indentation", lifts: ["R1", "r6"] }, { kind: "rule", words: "two-space indentation", lifts: ["R1", "R6"] }],
    ["exact words that replace two, in one string", { rule: "two-space indentation", lifts: "R1, R6" }, { kind: "rule", words: "two-space indentation", lifts: ["R1", "R6"] }],
    ["a target named twice counts once", "lifts R1, R1", { kind: "lift", targets: ["R1"] }],
  ];
  for (const [name, value, expected] of cases) assert.deepEqual(labelOf(value), expected, name);
});

test("labelOf: anything else is an error the retry note can show", () => {
  for (const value of ["maybe", "lifts", "lifts X2", "lifts R1, X2", "lifts R1,", 3, null, {}, { rule: "  " }, ["rule"], { lifts: [] }, { lifts: ["R1", 2] }]) {
    const label = labelOf(value);
    assert.equal(typeof label, "string", JSON.stringify(value));
    assert.match(label as string, /expected "rule"/);
  }
});

