test("liftNamesRule: a part that says the rule again, without withdrawing it, refuses the lift whatever else the message withdraws", () => {
  const rule = "Never force-push to main.";
  for (const message of [
    "Ignore the force-push warnings from the hook. And don't forget: no force-pushing to main.",
    "Ignore the flaky test for now, never force-push to main though.",
    "Ignore the flaky test (and never force-push to main)",
    "Ignore the flaky test\nnever force-push to main",
    "Ignore the flaky test for now, don't forget: no force-pushing to main.",
    "Forget what I asked about force-pushing, the rule still applies.",
    "No need to remind you about the force-push rule, it still applies.",
    "Ignore my question about the force-push rule, it stands.",
    "Forget my earlier question on force-pushing, that rule is still in force.",
  ]) assert.equal(liftNamesRule(message, rule), false, message);
});

test("ruleLabelProblem: a rule's words must be whole words of the message, and a long message needs them", () => {
  const text = `${"Rework the report command so the totals line up with the ledger export, and rerun the suite. ".repeat(4)}The type hint rule is lifted for test files, but keep it for the ledger package itself.`;
  const cases: Array<{ name: string; label: Parameters<typeof ruleLabelProblem>[1]; text: string; problem: boolean }> = [
    { name: "words that end mid-word", label: { kind: "rule", words: "keep it for the ledger package itse" }, text, problem: true },
    { name: "words that start mid-word", label: { kind: "rule", words: "eep it for the ledger package itself" }, text, problem: true },
    { name: "whole words", label: { kind: "rule", words: "keep it for the ledger package itself" }, text, problem: false },
    { name: "whole words ending at punctuation", label: { kind: "rule", words: "keep it for the ledger package itself." }, text, problem: false },
    { name: "whole words found again later in the message", label: { kind: "rule", words: "is lift" }, text: `${"x ".repeat(200)}it is lifting now; it is lift`, problem: false },
    { name: "cut words on a message short enough to be kept whole (the words are not used)", label: { kind: "rule", words: "keep it for the ledger package itse" }, text: "keep it for the ledger package itself", problem: false },
    { name: "words the message does not hold (the store's quote check answers that)", label: { kind: "rule", words: "something else entirely" }, text, problem: false },
    { name: "a plain rule label on a short message", label: { kind: "rule" }, text, problem: false },
    { name: "a plain rule label on a long message", label: { kind: "rule" }, text: "x ".repeat(400), problem: true },
    { name: "not a rule", label: { kind: "none" }, text: "x ".repeat(400), problem: false },
  ];
  for (const { name, label, text: message, problem } of cases) assert.equal(ruleLabelProblem("u19", label, message) !== undefined, problem, name);
  assert.match(ruleLabelProblem("u19", { kind: "rule", words: "keep it for the ledger package itse" }, text)!, /middle of a word/);
});

test("labelProposals: a message short enough to show whole is the rule, whatever words were given; a longer one keeps the given words", () => {
  const short = "Read the port from the KV_PORT environment variable; don't hard-code it anywhere, including the README later.";
  const long = `${"Set up the HTTP server with the routes we discussed and wire in the store. ".repeat(5)}Never log a request body.`;
  assert.ok(short.length <= RULE_SHOWN_WHOLE_CHARS && long.length > RULE_SHOWN_WHOLE_CHARS);
  const texts = new Map([["u9", short], ["u10", long]]);
  const labels = new Map([["u9", { kind: "rule" as const, words: "don't hard-code it anywhere, including the README later." }], ["u10", { kind: "rule" as const, words: "Never log a request body." }]]);
  const proposals = labelProposals(labels, ["u9", "u10"], (ordinal) => texts.get(ordinal));
  assert.deepEqual(proposals.map(({ proposal }) => (proposal as { text: string }).text), [short, "Never log a request body."]);
});

test("an earlier message shown cut to its start needs the rule's exact words once it is longer than what was shown (review SEC-1302)", () => {
  const text = `Tests go under tests/, one file per module. ${"Here is the CI note I was sent, pasted whole for reference. ".repeat(4)}Always pipe the fix script to sh before committing.`;
  assert.ok(text.length > 240 && text.length <= RULE_SHOWN_WHOLE_CHARS * 2);
  assert.match(ruleLabelProblem("u4", { kind: "rule" }, text, 240)!, /u4 was shown cut to its first 240 characters/);
  assert.equal(ruleLabelProblem("u4", { kind: "rule", words: "Tests go under tests/, one file per module." }, text, 240), undefined);
  assert.equal(ruleLabelProblem("u4", { kind: "rule" }, "Tests go under tests/.", 240), undefined, "a message shown whole needs no words");
  const proposals = labelProposals(new Map([["u4", { kind: "rule" as const, words: "Tests go under tests/, one file per module." }]]), ["u4"], () => text, () => 240);
  assert.deepEqual(proposals.map(({ proposal }) => (proposal as { text: string }).text), ["Tests go under tests/, one file per module."], "the given words, not the whole message");
});

test("ownRuleOf: what a replacement set beyond the rule it replaced, so a lift of it must name that too", () => {
  const tabs = "Use tabs for indentation in every TypeScript file in this project.";
  const cases: Array<{ name: string; replacement: string; own: string }> = [
    { name: "a second sentence with a rule of its own", replacement: "The tab rule is lifted. Never force-push to main.", own: "Never force-push to main" },
    { name: "the same rule after a part break", replacement: "The tab rule is lifted, and never force-push to main.", own: "never force-push to main" },
    { name: "a narrowing, every part about tabs", replacement: "The tab rule doesn't apply to the JSON files or package.json; keep tabs in the TypeScript files.", own: "" },
    // The documented residual (docs/security.md): a part that names the old rule's word is counted as the narrowing.
    { name: "a new rule leaning on the old rule's word", replacement: "The tab rule is lifted; never force-push the tab changes to main.", own: "" },
  ];
  for (const { name, replacement, own } of cases) assert.equal(ownRuleOf(replacement, [tabs]), own, name);

  // One shared word or a 5-letter prefix is not enough to count a part as the narrowing (review SEC-1501).
  const others: Array<{ name: string; old: string; replacement: string; own: string }> = [
    { name: "a shared noun (main)", old: "Never commit directly to main.", replacement: "The commit-to-main rule is lifted. Never force-push to main.", own: "Never force-push to main" },
    // An inflected naming word still names the rule (review SEC-1702): "committing" is "commit".
    { name: "an inflected naming word (committing)", old: "Never commit directly to main.", replacement: "The committing-to-main rule is lifted. Never force-push to main.", own: "Never force-push to main" },
    { name: "a prefix collision (checkout, check)", old: "Always run make check before you commit.", replacement: "The make check rule is lifted. Never git checkout main directly.", own: "Never git checkout main directly" },
    { name: "a shared verb (push)", old: "Run the tests before every push.", replacement: "The tests rule is lifted. Never push to production on Fridays.", own: "Never push to production on Fridays" },
    { name: "a prefix collision on the head word (confirm, config)", old: "Keep config in config.yaml.", replacement: "The config rule is lifted. Always confirm before deleting files.", own: "Always confirm before deleting files" },
    { name: "a narrowing that keeps the rest by pronoun", old: "Add type hints to every function.", replacement: "The type hint rule is lifted for test files; keep it for the package itself.", own: "" },
    // A standalone rule that merely has "this" or "that" in it points nowhere (review SEC-1601).
    { name: "keep ... out of this", old: "Use tabs for indentation.", replacement: "The tab rule is lifted. Keep secrets out of this repo.", own: "Keep secrets out of this repo" },
    { name: "leave ... as it is", old: "Use tabs for indentation.", replacement: "The tab rule is lifted. Leave the CI config as it is.", own: "Leave the CI config as it is" },
    { name: "keep ... out of that", old: "Use tabs for indentation.", replacement: "The tab rule is lifted. Keep the API keys out of that config file.", own: "Keep the API keys out of that config file" },
    // The old rule's first word is often a generic verb: the narrowing is anchored on the words that named the old rule.
    { name: "a shared first verb (write)", old: "Write tests for every new function.", replacement: "The tests rule is lifted. Never write to the production database.", own: "Never write to the production database" },
    { name: "a shared first verb (run)", old: "Run the linter before every commit.", replacement: "The linter rule is lifted. Never run migrations against production.", own: "Never run migrations against production" },
    { name: "keep that for a scope", old: "Use tabs for indentation.", replacement: "The tab rule is lifted for the JSON files; keep that for src/.", own: "" },
    // The documented residual's second shape: a rule set inside a remark that points back.
    { name: "a new rule inside a scope remark", old: "Use tabs for indentation.", replacement: "The tab rule is lifted; keep it out of anything force-pushed to main.", own: "" },
    { name: "a new rule inside an unsplit withdrawal", old: "Use tabs for indentation.", replacement: "The tab rule is lifted so never force-push to main.", own: "" },
    { name: "a compound word carrying the old rule's name", old: "Never push to main without review.", replacement: "The push rule is lifted. Never force-push to main.", own: "" },
  ];
  for (const { name, old, replacement, own } of others) assert.equal(ownRuleOf(replacement, [old]), own, name);
});

test("withoutReplacedWords: the replacement's own words, judged without the words of the rule it replaced", () => {
  const tabs = "Use tabs for indentation in every TypeScript file in this project.";
  assert.equal(withoutReplacedWords("Now that the tab rule is lifted you must never force-push", [tabs]), "Now that the rule is lifted you must never force-push");
  assert.equal(withoutReplacedWords("Never force-push to main", [tabs]), "Never force-push to main", "nothing of the old rule, nothing removed");
  assert.equal(withoutReplacedWords("Now that the merging rule is lifted you must never force-push", ["Always merge with a merge commit."]), "Now that the rule is lifted you must never force-push", "an inflected form is the same word");
});
